INSERT INTO public."Course" (id, title, status, ects, tagline, language, "applicationEnd", cost, "achievementCertificatePossible", "attendanceCertificatePossible", "maxMissedSessions", "weekDay", "coverImage", created_at, updated_at, "programId", "headingDescriptionField1", "headingDescriptionField2", "contentDescriptionField1", "contentDescriptionField2", "learningGoals", "chatLink", "maxParticipants", "endTime", "startTime", published, "externalRegistrationLink", "registrationType", "basePrice", currency, "guestRegistrationEnabled", "showAvailablePlaces", "registrationButtonLabelDe", "registrationButtonLabelEn", "sourceSessionId") VALUES
  (7201, 'KI-Stammtisch Kiel [Direkt · kostenlos]', 'APPLICANTS_INVITED', 'NONE', 'Lockerer Austausch über KI-Projekte bei einem Getränk.', 'DE', (now() AT TIME ZONE 'Europe/Berlin')::date + 13, '0', false, true, 0, 'NONE', NULL, '2026-04-20 05:00:00+00', '2026-04-20 05:00:00+00', 3, 'Worum geht es?', NULL, 'Ein Abend für alle, die mit KI arbeiten oder es vorhaben. Kurze Lightning Talks, danach Zeit zum Netzwerken.', NULL, NULL, 'https://chat.opencampus.sh', 60, '21:00'::time, '18:00'::time, true, NULL, 'DIRECT_CONFIRMATION', 0, 'EUR', false, true, NULL, NULL, NULL),
  (7202, 'Data Science Meetup Kiel [Direkt · mit Gästen]', 'APPLICANTS_INVITED', 'NONE', 'Zwei Talks aus der Praxis – Anmeldung auch ohne Account.', 'DE', (now() AT TIME ZONE 'Europe/Berlin')::date + 6, '0', false, true, 0, 'NONE', NULL, '2026-04-20 05:00:00+00', '2026-04-20 05:00:00+00', 3, 'Worum geht es?', NULL, 'Gäste können sich ohne EduHub-Account mit ihrer E-Mail-Adresse anmelden.', NULL, NULL, 'https://chat.opencampus.sh', 80, '20:00'::time, '18:00'::time, true, NULL, 'DIRECT_CONFIRMATION', 0, 'EUR', true, false, NULL, NULL, NULL),
  (7203, 'Prototyping-Workshop [Direkt mit Angaben · mit Gästen]', 'APPLICANTS_INVITED', 'NONE', 'In drei Stunden vom Problem zum klickbaren Prototyp.', 'DE', (now() AT TIME ZONE 'Europe/Berlin')::date + 9, '0', false, true, 0, 'NONE', NULL, '2026-04-20 05:00:00+00', '2026-04-20 05:00:00+00', 3, 'Worum geht es?', NULL, 'Bei der Anmeldung fragen wir kurz nach Deinem Vorwissen, damit wir die Gruppen passend zusammenstellen.', NULL, NULL, 'https://chat.opencampus.sh', 30, '17:00'::time, '14:00'::time, true, NULL, 'DIRECT_WITH_INPUT', 0, 'EUR', true, true, NULL, NULL, NULL),
  (7204, 'Prompt Engineering Masterclass [Bezahlt · direkt]', 'APPLICANTS_INVITED', 'NONE', 'Ein Tag intensives Training für bessere Prompts und Agenten.', 'DE', (now() AT TIME ZONE 'Europe/Berlin')::date + 19, '0', false, true, 0, 'NONE', NULL, '2026-04-20 05:00:00+00', '2026-04-20 05:00:00+00', 3, 'Worum geht es?', NULL, 'Die Teilnahme kostet 49 € inkl. MwSt. Nach der Zahlung ist Dein Platz sicher.', NULL, NULL, 'https://chat.opencampus.sh', 25, '16:00'::time, '10:00'::time, true, NULL, 'DIRECT_CONFIRMATION_AND_PAYMENT', 4900, 'EUR', false, true, 'Ticket kaufen', 'Buy ticket', NULL),
  (7205, 'Waterkant Festival Tagesticket [Bezahlt · mit Angaben]', 'APPLICANTS_INVITED', 'NONE', 'Ein Tag Festival mit Talks, Workshops und Ausstellung.', 'DE', (now() AT TIME ZONE 'Europe/Berlin')::date + 26, '0', false, true, 0, 'NONE', NULL, '2026-04-20 05:00:00+00', '2026-04-20 05:00:00+00', 3, 'Worum geht es?', NULL, 'Bei der Anmeldung wählst Du Deine Workshop-Präferenzen aus. Das Ticket kostet 25 € inkl. MwSt.', NULL, NULL, 'https://chat.opencampus.sh', 200, '18:00'::time, '09:00'::time, true, NULL, 'DIRECT_WITH_INPUT_AND_PAYMENT', 2500, 'EUR', false, false, 'Ticket sichern', 'Get ticket', NULL),
  (7206, 'Coding Camp 2026 [Bewerbung]', 'APPLICANTS_INVITED', 'NONE', 'Drei Tage Machine Learning an echten Problemen – mit Bewerbung.', 'DE', (now() AT TIME ZONE 'Europe/Berlin')::date + 21, '0', false, true, 0, 'NONE', NULL, '2026-04-20 05:00:00+00', '2026-04-20 05:00:00+00', 3, 'Worum geht es?', NULL, 'Die Plätze sind begrenzt. Erzähl uns in Deiner Bewerbung, woran Du arbeiten möchtest.', NULL, NULL, 'https://chat.opencampus.sh', 40, '18:00'::time, '10:00'::time, true, NULL, 'APPROVAL_WITH_INPUT', 0, 'EUR', false, false, NULL, NULL, NULL),
  (7207, 'Waterkant Festival 2026 [Externe Anmeldung]', 'APPLICANTS_INVITED', 'NONE', 'Das Festival für Innovation und Gründung an der Kieler Förde.', 'DE', (now() AT TIME ZONE 'Europe/Berlin')::date + 44, '0', false, true, 0, 'NONE', NULL, '2026-04-20 05:00:00+00', '2026-04-20 05:00:00+00', 3, 'Worum geht es?', NULL, 'Die Anmeldung läuft über die Website des Festivals.', NULL, NULL, 'https://chat.opencampus.sh', NULL, '20:00'::time, '10:00'::time, true, 'https://example.com/waterkant-festival', 'EXTERNAL_REGISTRATION', 0, 'EUR', false, false, 'Zur Festival-Anmeldung', 'Register on the festival website', NULL),
  (7208, 'AI Founders Breakfast [Ausgebucht · Warteliste]', 'APPLICANTS_INVITED', 'NONE', 'Frühstück mit Gründer:innen aus der KI-Szene – nur 12 Plätze.', 'DE', (now() AT TIME ZONE 'Europe/Berlin')::date + 8, '0', false, true, 0, 'NONE', NULL, '2026-04-20 05:00:00+00', '2026-04-20 05:00:00+00', 3, 'Worum geht es?', NULL, 'Alle Plätze sind vergeben. Trag Dich in die Warteliste ein, wir melden uns, sobald etwas frei wird.', NULL, NULL, 'https://chat.opencampus.sh', 12, '10:00'::time, '08:00'::time, true, NULL, 'DIRECT_CONFIRMATION', 0, 'EUR', false, true, NULL, NULL, NULL),
  (7209, 'Prototyping Week [Läuft · Bewerbung]', 'APPLICANTS_INVITED', 'NONE', 'Eine Woche lang im Team einen KI-Prototyp bauen.', 'DE', (now() AT TIME ZONE 'Europe/Berlin')::date + -10, '0', false, true, 0, 'NONE', NULL, '2026-04-20 05:00:00+00', '2026-04-20 05:00:00+00', 3, 'Worum geht es?', NULL, 'Die Prototyping Week läuft gerade. Bewerbungen sind geschlossen.', NULL, NULL, 'https://chat.opencampus.sh', 30, '17:00'::time, '09:00'::time, true, NULL, 'APPROVAL_WITH_INPUT', 0, 'EUR', false, false, NULL, NULL, NULL),
  (7210, 'Coding.Waterkant Meetup-Reihe [Läuft · Direkt · mit Gästen]', 'APPLICANTS_INVITED', 'NONE', 'Monatliches Meetup der Coding.Waterkant Community – vor Ort und online.', 'DE', (now() AT TIME ZONE 'Europe/Berlin')::date + 40, '0', false, true, 0, 'NONE', NULL, '2026-04-20 05:00:00+00', '2026-04-20 05:00:00+00', 3, 'Worum geht es?', NULL, 'Melde Dich einmal an und sei bei allen Terminen der Reihe dabei.', NULL, NULL, 'https://chat.opencampus.sh', NULL, '20:00'::time, '18:00'::time, true, NULL, 'DIRECT_CONFIRMATION', 0, 'EUR', true, false, NULL, NULL, NULL),
  (7211, 'Coding Camp 2025 [Vergangen · Bewerbung]', 'APPLICANTS_INVITED', 'NONE', 'Drei Tage Machine Learning an echten Problemen.', 'DE', '2025-08-31'::date, '0', false, true, 0, 'NONE', NULL, '2026-04-20 05:00:00+00', '2026-04-20 05:00:00+00', 10, 'Worum geht es?', NULL, 'Das Coding Camp 2025 ist vorbei. Danke an alle Teams!', NULL, NULL, 'https://chat.opencampus.sh', 40, '18:00'::time, '10:00'::time, true, NULL, 'APPROVAL_WITH_INPUT', 0, 'EUR', false, false, NULL, NULL, NULL),
  (7212, 'Data Science Meetup Juni [Vergangen · Direkt · mit Gästen]', 'APPLICANTS_INVITED', 'NONE', 'Zwei Talks aus der Praxis.', 'DE', '2025-06-12'::date, '0', false, true, 0, 'NONE', NULL, '2026-04-20 05:00:00+00', '2026-04-20 05:00:00+00', 10, 'Worum geht es?', NULL, 'Das Meetup ist vorbei. Die Folien findest Du im Community-Chat.', NULL, NULL, 'https://chat.opencampus.sh', 80, '20:00'::time, '18:00'::time, true, NULL, 'DIRECT_CONFIRMATION', 0, 'EUR', true, false, NULL, NULL, NULL),
  (7213, 'Prompt Engineering Masterclass Frühjahr [Vergangen · Bezahlt]', 'APPLICANTS_INVITED', 'NONE', 'Ein Tag intensives Training für bessere Prompts.', 'DE', '2026-03-13'::date, '0', false, true, 0, 'NONE', NULL, '2026-04-20 05:00:00+00', '2026-04-20 05:00:00+00', 10, 'Worum geht es?', NULL, 'Die Masterclass ist vorbei.', NULL, NULL, 'https://chat.opencampus.sh', 25, '16:00'::time, '10:00'::time, true, NULL, 'DIRECT_CONFIRMATION_AND_PAYMENT', 4900, 'EUR', false, false, NULL, NULL, NULL),
  (7214, 'Tech Talk: LLMs in Produktion [Vergangen · Direkt mit Angaben · online]', 'APPLICANTS_INVITED', 'NONE', 'Online-Talk über Monitoring, Kosten und Evaluierung von LLM-Anwendungen.', 'DE', '2026-02-05'::date, '0', false, true, 0, 'NONE', NULL, '2026-04-20 05:00:00+00', '2026-04-20 05:00:00+00', 10, 'Worum geht es?', NULL, 'Der Talk ist vorbei.', NULL, NULL, 'https://chat.opencampus.sh', NULL, '19:00'::time, '18:00'::time, true, NULL, 'DIRECT_WITH_INPUT', 0, 'EUR', false, false, NULL, NULL, NULL)
